insert into public.questions(id,subject_id,topic_id,text,status,is_public,is_sample) values('00000004-0000-4000-8000-000000000001','00000001-0000-4000-8000-000000000001','00000002-0000-4000-8000-000000000001','3x + 7 = 22 tenglamani qanday yechaman?','solved_by_forum',true,true) on conflict(id) do nothing;
insert into public.answers(id,question_id,author_name,steps,is_sample) values('00000005-0000-4000-8000-000000000001','00000004-0000-4000-8000-000000000001','EduBridge jamoasi (namunaviy)','["7 ni tenglikning o‘ng tomoniga ishorasini o‘zgartirib o‘tkazamiz: 3x = 22 − 7.","O‘ng tomonni hisoblaymiz: 3x = 15.","Ikkala tomonni 3 ga bo‘lamiz: x = 15 ÷ 3 = 5.","Tekshiramiz: 3 · 5 + 7 = 22. To‘g‘ri."]'::jsonb,true) on conflict(id) do nothing;
insert into public.questions(id,subject_id,topic_id,text,status,is_public,is_sample) values('00000004-0000-4000-8000-000000000002','00000001-0000-4000-8000-000000000001','00000002-0000-4000-8000-000000000002','2x − 3 > 5 tengsizlikni qanday yechaman?','solved_by_forum',true,true) on conflict(id) do nothing;
insert into public.answers(id,question_id,author_name,steps,is_sample) values('00000005-0000-4000-8000-000000000002','00000004-0000-4000-8000-000000000002','EduBridge jamoasi (namunaviy)','["Ikkala tomonga 3 ni qo‘shamiz: 2x > 8.","Ikkala tomonni musbat 2 ga bo‘lamiz, belgi o‘zgarmaydi.","Natija: x > 4. Masalan, x = 5 bo‘lsa, 7 > 5."]'::jsonb,true) on conflict(id) do nothing;
insert into public.questions(id,subject_id,topic_id,text,status,is_public,is_sample) values('00000004-0000-4000-8000-000000000003','00000001-0000-4000-8000-000000000001','00000002-0000-4000-8000-000000000003','√49 + √16 ifodaning qiymati qancha?','solved_by_forum',true,true) on conflict(id) do nothing;
insert into public.answers(id,question_id,author_name,steps,is_sample) values('00000005-0000-4000-8000-000000000003','00000004-0000-4000-8000-000000000003','EduBridge jamoasi (namunaviy)','["Kvadrat ildizni topish uchun qaysi sonning kvadrati berilgan songa tengligini izlaymiz.","7² = 49, shuning uchun √49 = 7.","4² = 16, shuning uchun √16 = 4.","Yig‘indi: 7 + 4 = 11."]'::jsonb,true) on conflict(id) do nothing;
insert into public.questions(id,subject_id,topic_id,text,status,is_public,is_sample) values('00000004-0000-4000-8000-000000000004','00000001-0000-4000-8000-000000000001','00000002-0000-4000-8000-000000000004','x² − 9 = 0 tenglamani qanday yechaman?','solved_by_forum',true,true) on conflict(id) do nothing;
insert into public.answers(id,question_id,author_name,steps,is_sample) values('00000005-0000-4000-8000-000000000004','00000004-0000-4000-8000-000000000004','EduBridge jamoasi (namunaviy)','["Ikkala tomonga 9 qo‘shamiz: x² = 9.","Kvadrati 9 bo‘ladigan sonlar 3 va −3.","Javob: x = 3 yoki x = −3. Ikkalasi ham tenglamani qanoatlantiradi."]'::jsonb,true) on conflict(id) do nothing;
insert into public.questions(id,subject_id,topic_id,text,status,is_public,is_sample) values('00000004-0000-4000-8000-000000000005','00000001-0000-4000-8000-000000000002','00000002-0000-4000-8000-000000000007','Massasi 200 g, hajmi 50 cm³ bo‘lgan jismning zichligi qancha?','solved_by_forum',true,true) on conflict(id) do nothing;
insert into public.answers(id,question_id,author_name,steps,is_sample) values('00000005-0000-4000-8000-000000000005','00000004-0000-4000-8000-000000000005','EduBridge jamoasi (namunaviy)','["Zichlik formulasi: ρ = m / V (massa bo‘lingan hajm).","Qiymatlarni qo‘yamiz: ρ = 200 g / 50 cm³.","Hisoblaymiz: ρ = 4 g/cm³.","Birlikni tekshiramiz: g/cm³ — zichlik birligi. Javob: 4 g/cm³."]'::jsonb,true) on conflict(id) do nothing;
insert into public.questions(id,subject_id,topic_id,text,status,is_public,is_sample) values('00000004-0000-4000-8000-000000000006','00000001-0000-4000-8000-000000000002','00000002-0000-4000-8000-000000000006','Avtobus 120 km yo‘lni 2 soatda bosib o‘tdi. O‘rtacha tezligi qancha?','solved_by_forum',true,true) on conflict(id) do nothing;
insert into public.answers(id,question_id,author_name,steps,is_sample) values('00000005-0000-4000-8000-000000000006','00000004-0000-4000-8000-000000000006','EduBridge jamoasi (namunaviy)','["O‘rtacha tezlik formulasi: v = s / t.","Masofa s = 120 km, vaqt t = 2 soat.","v = 120 / 2 = 60 km/soat."]'::jsonb,true) on conflict(id) do nothing;
insert into public.questions(id,subject_id,topic_id,text,status,is_public,is_sample) values('00000004-0000-4000-8000-000000000007','00000001-0000-4000-8000-000000000002','00000002-0000-4000-8000-000000000008','100 N kuch 2 m² yuzaga ta’sir qilsa, bosim qancha bo‘ladi?','solved_by_forum',true,true) on conflict(id) do nothing;
insert into public.answers(id,question_id,author_name,steps,is_sample) values('00000005-0000-4000-8000-000000000007','00000004-0000-4000-8000-000000000007','EduBridge jamoasi (namunaviy)','["Bosim formulasi: p = F / S.","Kuch F = 100 N, yuza S = 2 m².","p = 100 / 2 = 50 Pa. 1 Pa = 1 N/m²."]'::jsonb,true) on conflict(id) do nothing;
insert into public.questions(id,subject_id,topic_id,text,status,is_public,is_sample) values('00000004-0000-4000-8000-000000000008','00000001-0000-4000-8000-000000000002','00000002-0000-4000-8000-000000000009','Massasi 2 kg jism 3 m/s² tezlanish olsa, kuch qancha?','solved_by_forum',true,true) on conflict(id) do nothing;
insert into public.answers(id,question_id,author_name,steps,is_sample) values('00000005-0000-4000-8000-000000000008','00000004-0000-4000-8000-000000000008','EduBridge jamoasi (namunaviy)','["Nyutonning ikkinchi qonuni: F = m · a.","m = 2 kg va a = 3 m/s² ni qo‘yamiz.","F = 2 · 3 = 6 N."]'::jsonb,true) on conflict(id) do nothing;
insert into public.questions(id,subject_id,topic_id,text,status,is_public,is_sample) values('00000004-0000-4000-8000-000000000009','00000001-0000-4000-8000-000000000003','00000002-0000-4000-8000-000000000013','H₂O da kislorodning valentligi nechaga teng?','solved_by_forum',true,true) on conflict(id) do nothing;
insert into public.answers(id,question_id,author_name,steps,is_sample) values('00000005-0000-4000-8000-000000000009','00000004-0000-4000-8000-000000000009','EduBridge jamoasi (namunaviy)','["Vodorodning valentligi doim I ga teng.","Formulada 2 ta vodorod atomi bor: umumiy valentlik birliklari 2 · I = 2.","Bu 2 birlik bitta kislorod atomiga to‘g‘ri keladi.","Demak, kislorodning valentligi II ga teng."]'::jsonb,true) on conflict(id) do nothing;
insert into public.questions(id,subject_id,topic_id,text,status,is_public,is_sample) values('00000004-0000-4000-8000-000000000010','00000001-0000-4000-8000-000000000003','00000002-0000-4000-8000-000000000012','CO₂ ning nisbiy molekulyar massasini qanday topaman?','solved_by_forum',true,true) on conflict(id) do nothing;
insert into public.answers(id,question_id,author_name,steps,is_sample) values('00000005-0000-4000-8000-000000000010','00000004-0000-4000-8000-000000000010','EduBridge jamoasi (namunaviy)','["Nisbiy atom massalari: C = 12, O = 16.","CO₂ tarkibida 1 ta uglerod va 2 ta kislorod atomi bor.","Mr(CO₂) = 12 + 2 · 16 = 44. Nisbiy molekulyar massa birliksiz."]'::jsonb,true) on conflict(id) do nothing;
insert into public.questions(id,subject_id,topic_id,text,status,is_public,is_sample) values('00000004-0000-4000-8000-000000000011','00000001-0000-4000-8000-000000000003','00000002-0000-4000-8000-000000000014','H₂ + O₂ → H₂O reaksiya tenglamasini qanday tenglashtiraman?','solved_by_forum',true,true) on conflict(id) do nothing;
insert into public.answers(id,question_id,author_name,steps,is_sample) values('00000005-0000-4000-8000-000000000011','00000004-0000-4000-8000-000000000011','EduBridge jamoasi (namunaviy)','["Kislorod chapda 2 ta, o‘ngda 1 ta. Suv oldiga 2 qo‘yamiz.","O‘ngda 4 ta vodorod hosil bo‘ldi. H₂ oldiga 2 qo‘yamiz.","Tenglama: 2H₂ + O₂ → 2H₂O. Har ikki tomonda H: 4 ta, O: 2 ta."]'::jsonb,true) on conflict(id) do nothing;
insert into public.questions(id,subject_id,topic_id,text,status,is_public,is_sample) values('00000004-0000-4000-8000-000000000012','00000001-0000-4000-8000-000000000003','00000002-0000-4000-8000-000000000015','36 g suvning modda miqdori necha mol?','solved_by_forum',true,true) on conflict(id) do nothing;
insert into public.answers(id,question_id,author_name,steps,is_sample) values('00000005-0000-4000-8000-000000000012','00000004-0000-4000-8000-000000000012','EduBridge jamoasi (namunaviy)','["Formula: n = m / M.","Suvning molyar massasi M(H₂O) = 2 · 1 + 16 = 18 g/mol.","n = 36 g / 18 g/mol = 2 mol."]'::jsonb,true) on conflict(id) do nothing;
