-- Team-written examples only. All sample entities are explicitly marked.
begin;
-- Four future fifteen-minute slots for every sample teacher; safe to rerun.
select t.id, s.start_time, s.start_time+interval '15 minutes'
from public.teachers t
cross join lateral (select ((now() at time zone 'Asia/Tashkent')::date+d.day+h.hour)::timestamp at time zone 'Asia/Tashkent' as start_time from generate_series(0,3) d(day) cross join (values(time '09:00'),(time '14:00'),(time '17:00')) h(hour) where ((now() at time zone 'Asia/Tashkent')::date+d.day+h.hour)::timestamp at time zone 'Asia/Tashkent'>now() order by start_time limit 4) s
where t.is_sample on conflict(teacher_id,starts_at) do nothing;
-- The demo profile is created on first demo login, not as a fake auth user in SQL.
commit;

